import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The mesh warp's five moves, one keyframe stride each: the middle column
// sliding right, the middle row dropping, the column sliding left, the row
// rising, and both easing home. Frames on the 30 fps scene timeline. The ids
// are public: a saved `timing` prop refers to them.

type KineticWarpElementId = "right" | "down" | "left" | "up" | "home";

interface KineticWarpTimingProps {
  keyframeStride?: number;
}

const KEYFRAME_STRIDE = 20;

/** The moves in order; each runs from one keyframe to the next. */
const KINETIC_WARP_MOVES = [
  "right",
  "down",
  "left",
  "up",
  "home",
] as const satisfies readonly KineticWarpElementId[];

const LABELS: Record<KineticWarpElementId, string> = {
  right: "Column right",
  down: "Row down",
  left: "Column left",
  up: "Row up",
  home: "Home",
};

// Each move follows the one before it.
const kineticWarpTimeline = defineTimeline<
  KineticWarpElementId,
  KineticWarpTimingProps
>(({ keyframeStride = KEYFRAME_STRIDE }) =>
  KINETIC_WARP_MOVES.map((id, k) => ({
    id,
    lane: "Warp",
    label: LABELS[id],
    start: k * keyframeStride,
    length: keyframeStride,
    follows: k > 0 ? KINETIC_WARP_MOVES[k - 1] : undefined,
  })),
);

interface KineticWarpProps {
  className?: string;
  compWidth?: number;
  compHeight?: number;
  textColor?: string;
  text?: string;
  fontFamily?: string;
  fontUrl?: string;
  fontWeight?: number;
  fontSize?: number;
  leading?: number;
  tracking?: number;
  layerScale?: number;
  positionX?: number;
  positionY?: number;
  meshRows?: number;
  meshColumns?: number;
  colRestX?: number;
  colRightX?: number;
  colLeftX?: number;
  rowRestY?: number;
  rowDownY?: number;
  rowUpY?: number;
  keyframeStride?: number;
  easingBezier?: [number, number, number, number];
  resampleStep?: number;
  /**
   * Moves, trims or stretches single moves of the warp, by the ids in
   * `./timeline`. Frames on the scene timeline.
   */
  timing?: Timing<KineticWarpElementId>;
}

function monotoneSpline(xs: number[], ys: number[]): (x: number) => number {
  const n = xs.length;
  const dx: number[] = [];
  const secant: number[] = [];
  for (let i = 0; i < n - 1; i++) {
    dx.push(xs[i + 1] - xs[i]);
    secant.push((ys[i + 1] - ys[i]) / (xs[i + 1] - xs[i]));
  }

  const m: number[] = new Array(n);
  m[0] = secant[0];
  m[n - 1] = secant[n - 2];
  for (let i = 1; i < n - 1; i++) {
    m[i] = secant[i - 1] * secant[i] <= 0 ? 0 : (secant[i - 1] + secant[i]) / 2;
  }

  for (let i = 0; i < n - 1; i++) {
    if (secant[i] === 0) {
      m[i] = 0;
      m[i + 1] = 0;
      continue;
    }
    const a = m[i] / secant[i];
    const b = m[i + 1] / secant[i];
    const s = a * a + b * b;
    if (s > 9) {
      const t = 3 / Math.sqrt(s);
      m[i] = t * a * secant[i];
      m[i + 1] = t * b * secant[i];
    }
  }

  return (x: number) => {
    if (x <= xs[0]) return ys[0] + m[0] * (x - xs[0]);
    if (x >= xs[n - 1]) return ys[n - 1] + m[n - 1] * (x - xs[n - 1]);
    let i = n - 2;
    while (i > 0 && x < xs[i]) i--;
    const h = dx[i];
    const t = (x - xs[i]) / h;
    const t2 = t * t;
    const t3 = t2 * t;
    return (
      (2 * t3 - 3 * t2 + 1) * ys[i] +
      (t3 - 2 * t2 + t) * h * m[i] +
      (-2 * t3 + 3 * t2) * ys[i + 1] +
      (t3 - t2) * h * m[i + 1]
    );
  };
}

function KineticWarpBase(props: KineticWarpProps) {
  const {
    className,
    compWidth = 1920,
    compHeight = 1080,
    textColor = "#FFFFFF",
    text = "REM\nOCN",
    fontFamily = "sans-serif",
    fontUrl = "",
    fontWeight = 700,
    fontSize = 107.1,
    leading = 70,
    tracking = -21,
    layerScale = 480,
    positionX = 960,
    positionY = 540,
    meshRows = 2,
    meshColumns = 4,
    colRestX = 960,
    colRightX = 1255,
    colLeftX = 678,
    rowRestY = 540,
    rowDownY = 850,
    rowUpY = 387,
    easingBezier = [0.3, 0.74, 0.09, 1],
    resampleStep = 4,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { durationInFrames } = useSceneConfig();
  const tl = useTimeline(kineticWarpTimeline, props, durationInFrames, timing);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [fontReady, setFontReady] = useState(false);

  const scale = layerScale / 100;
  const pxSize = fontSize * scale;
  const pxLeading = leading * scale;
  const pxTracking = (tracking / 1000) * pxSize;

  useEffect(() => {
    const handle = delayRender("kinetic-warp: loading font");
    let cancelled = false;
    const done = () => {
      if (!cancelled) setFontReady(true);
      continueRender(handle);
    };
    if (typeof document === "undefined" || !document.fonts) {
      done();
      return;
    }
    document.fonts
      .load(`${fontWeight} ${pxSize}px "${fontFamily}"`)
      .then(done, done);
    return () => {
      cancelled = true;
    };
  }, [fontFamily, fontWeight, pxSize]);

  const source = useMemo(() => {
    if (!fontReady || typeof document === "undefined") return null;
    const canvas = document.createElement("canvas");
    canvas.width = compWidth;
    canvas.height = compHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return null;

    ctx.font = `${fontWeight} ${pxSize}px "${fontFamily}", sans-serif`;
    ctx.letterSpacing = `${pxTracking}px`;
    ctx.fillStyle = textColor;
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";

    const lines = text.split("\n");
    const metrics = lines.map((line) => ctx.measureText(line));

    const ascent = metrics[0].actualBoundingBoxAscent;
    const descent = metrics[metrics.length - 1].actualBoundingBoxDescent;
    const span = (lines.length - 1) * pxLeading;
    const firstBaseline = positionY - (span - ascent + descent) / 2;

    lines.forEach((line, i) => {
      const m = metrics[i];
      const x =
        positionX - (m.actualBoundingBoxRight - m.actualBoundingBoxLeft) / 2;
      ctx.fillText(line, x, firstBaseline + i * pxLeading);
    });

    return canvas;
  }, [
    compWidth,
    compHeight,
    text,
    fontFamily,
    fontWeight,
    pxSize,
    pxLeading,
    pxTracking,
    textColor,
    positionX,
    positionY,
    fontReady,
  ]);

  const scratch = useMemo(() => {
    if (typeof document === "undefined") return null;
    const canvas = document.createElement("canvas");
    canvas.width = compWidth;
    canvas.height = compHeight;
    return canvas;
  }, [compWidth, compHeight]);

  const easing = Easing.bezier(...easingBezier);
  const clamp = {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  } as const;

  // One keyframe per move boundary. The move the frame is in is the first
  // whose end it has not passed, as `interpolate` picks the segment of a
  // multi-stop range; a frame between two moves holds the next one's start.
  const moves = KINETIC_WARP_MOVES.map((id) => tl.get(id));
  const keyed = (values: number[]) => {
    let k = 0;
    while (k < moves.length - 1 && moves[k].end < frame) k++;
    return interpolate(
      frame,
      [moves[k].start, moves[k].end],
      [values[k], values[k + 1]],
      clamp,
    );
  };
  const colX = keyed([
    colRestX,
    colRightX,
    colRightX,
    colLeftX,
    colLeftX,
    colRestX,
  ]);
  const rowY = keyed([
    rowRestY,
    rowRestY,
    rowDownY,
    rowDownY,
    rowUpY,
    rowRestY,
  ]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !source || !scratch) return;
    const out = canvas.getContext("2d");
    const mid = scratch.getContext("2d");
    if (!out || !mid) return;

    const xs = Array.from(
      { length: meshColumns + 1 },
      (_, i) => (i * compWidth) / meshColumns,
    );
    const ys = Array.from(
      { length: meshRows + 1 },
      (_, i) => (i * compHeight) / meshRows,
    );
    const xd = xs.slice();
    const yd = ys.slice();
    xd[Math.round(meshColumns / 2)] = colX;
    yd[Math.round(meshRows / 2)] = rowY;

    const gx = monotoneSpline(xd, xs);
    const gy = monotoneSpline(yd, ys);

    mid.clearRect(0, 0, compWidth, compHeight);
    out.clearRect(0, 0, compWidth, compHeight);

    for (let d0 = 0; d0 < compWidth; d0 += resampleStep) {
      const d1 = Math.min(d0 + resampleStep, compWidth);
      const s0 = gx(d0);
      const sw = gx(d1) - s0;
      if (sw <= 0) continue;
      mid.drawImage(source, s0, 0, sw, compHeight, d0, 0, d1 - d0, compHeight);
    }

    for (let d0 = 0; d0 < compHeight; d0 += resampleStep) {
      const d1 = Math.min(d0 + resampleStep, compHeight);
      const s0 = gy(d0);
      const sh = gy(d1) - s0;
      if (sh <= 0) continue;
      out.drawImage(scratch, 0, s0, compWidth, sh, 0, d0, compWidth, d1 - d0);
    }
  }, [
    source,
    scratch,
    colX,
    rowY,
    compWidth,
    compHeight,
    meshRows,
    meshColumns,
    resampleStep,
  ]);

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, overflow: "hidden" }}
    >
      {fontUrl ? <link rel="stylesheet" href={fontUrl} /> : null}
      <canvas
        ref={canvasRef}
        width={compWidth}
        height={compHeight}
        style={{ width: "100%", height: "100%", display: "block" }}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "REM\nOCN",
    description: "Text",
  },
  textColor: {
    type: "color",
    default: "#FFFFFF",
    description: "Color",
  },
  fontFamily: {
    type: "text-content",
    default: "Passion One",
    description: "Font family",
  },
  fontUrl: {
    type: "text-content",
    default: "https://fonts.googleapis.com/css2?family=Passion+One:wght@400;700;900&display=block",
    description: "Font URL",
  },
  fontWeight: {
    type: "enum",
    default: "700",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  fontSize: {
    type: "number",
    min: 40,
    max: 200,
    step: 0.1,
    default: 107.1,
    description: "Font size",
    hiddenFromList: false,
  },
  layerScale: {
    type: "number",
    min: 100,
    max: 800,
    step: 10,
    default: 480,
    description: "Layer scale (%)",
    hiddenFromList: false,
  },
  keyframeStride: {
    type: "number",
    min: 5,
    max: 40,
    step: 1,
    default: 20,
    description: "Keyframe stride",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","textColor","fontFamily","fontUrl","fontWeight","fontSize","layerScale","keyframeStride","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "REM\nOCN",
  textColor: "#FFFFFF",
  fontFamily: "Passion One",
  fontUrl: "https://fonts.googleapis.com/css2?family=Passion+One:wght@400;700;900&display=block",
  fontWeight: "700",
  fontSize: 107.1,
  layerScale: 480,
  keyframeStride: 20,
  speed: 1,
};

type KineticWarpElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof KineticWarpBase>;

const KineticWarpInner = forwardRef<
  HTMLDivElement,
  KineticWarpElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<KineticWarp>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <KineticWarpBase
          {...(componentProps as unknown as ComponentProps<typeof KineticWarpBase>)}
        />
      </div>
    </Sequence>
  );
});

export const KineticWarp = Interactive.withSchema({
  Component: KineticWarpInner,
  componentName: "<KineticWarp>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
